/**
 * Optional LLM layer.
 *
 * Attentio is fully useful with no AI at all. When the user turns it on, this
 * speaks the OpenAI chat-completions protocol — which is also what DeepSeek,
 * Moonshot, SiliconFlow, Ollama, LM Studio and vLLM speak — so "bring your own
 * key", "run it locally" and "point it at a company gateway" are one code path.
 *
 * Nothing here decides *what* leaves the machine; that is `buildRedactedPayload`
 * in report.ts, so the preview the user approves is generated by the same
 * function that produces the request body.
 */

import type { DayStats, JournalEntry } from '@attentio/shared';

import {
  buildRedactedPayload,
  renderReportMarkdown,
  reportPrompts,
  type Locale,
  type RedactionLevel,
} from './report.ts';

export interface AiClientConfig {
  baseUrl: string;
  apiKey: string;
  model: string;
  timeoutMs?: number;
}

export interface AiOutcome {
  ok: boolean;
  text: string;
  model: string;
  error?: string;
  /** True when the text came from the offline generator rather than a model. */
  fellBack: boolean;
}

/** Normalise a base URL to the chat-completions endpoint. */
export function chatEndpoint(baseUrl: string): string {
  const trimmed = baseUrl.trim().replace(/\/+$/, '');
  if (trimmed === '') return 'https://api.openai.com/v1/chat/completions';
  if (/\/chat\/completions$/.test(trimmed)) return trimmed;
  if (/\/v\d+$/.test(trimmed)) return `${trimmed}/chat/completions`;
  return `${trimmed}/v1/chat/completions`;
}

export async function chat(
  config: AiClientConfig,
  messages: { role: 'system' | 'user'; content: string }[],
): Promise<AiOutcome> {
  const endpoint = chatEndpoint(config.baseUrl);
  const controller = new AbortController();
  // A local model on a cold start can be slow, but an unbounded wait is worse
  // than an honest fallback.
  const timeout = setTimeout(() => controller.abort(), config.timeoutMs ?? 60_000);

  try {
    const response = await fetch(endpoint, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        ...(config.apiKey ? { authorization: `Bearer ${config.apiKey}` } : {}),
      },
      body: JSON.stringify({
        model: config.model,
        messages,
        temperature: 0.4,
        stream: false,
      }),
      signal: controller.signal,
    });

    if (!response.ok) {
      const detail = await response.text().catch(() => '');
      return {
        ok: false,
        text: '',
        model: config.model,
        error: `HTTP ${response.status} ${response.statusText}${detail ? `: ${detail.slice(0, 300)}` : ''}`,
        fellBack: false,
      };
    }

    const body = (await response.json()) as {
      choices?: { message?: { content?: string } }[];
      model?: string;
    };
    const text = body.choices?.[0]?.message?.content?.trim() ?? '';
    if (!text) {
      return { ok: false, text: '', model: config.model, error: 'The model returned an empty reply.', fellBack: false };
    }
    return { ok: true, text, model: body.model ?? config.model, fellBack: false };
  } catch (error) {
    const message =
      error instanceof Error
        ? error.name === 'AbortError'
          ? `Timed out after ${Math.round((config.timeoutMs ?? 60_000) / 1000)}s`
          : error.message
        : String(error);
    return { ok: false, text: '', model: config.model, error: message, fellBack: false };
  } finally {
    clearTimeout(timeout);
  }
}

export interface GenerateNarrativeOptions {
  ai: AiClientConfig & { enabled: boolean };
  stats: DayStats;
  journal: readonly JournalEntry[];
  locale: Locale;
  redaction: RedactionLevel;
  instruction?: string;
  /** Skip the network entirely and return the offline diagnosis. */
  statsOnly?: boolean;
}

/**
 * Produce the narrative for a report.
 *
 * Falls back to the deterministic generator on *any* failure — a missing key, a
 * dead endpoint, a rate limit, an empty completion. The user still gets their
 * report; they just also get told why it is the offline one.
 */
export async function generateNarrative(options: GenerateNarrativeOptions): Promise<AiOutcome> {
  const offline = { text: renderReportMarkdown(options.stats, { locale: options.locale, journal: options.journal }) };

  if (options.statsOnly || !options.ai.enabled || !options.ai.model) {
    return { ok: true, text: offline.text, model: 'offline', fellBack: false };
  }

  const payloadPreview = buildRedactedPayload(options.stats, options.journal, {
    level: options.redaction,
    locale: options.locale,
  });

  const { system, user } = reportPrompts(options.stats, options.locale, options.instruction);
  // The prompts embed their own payload; make sure the previewed payload and the
  // sent one describe the same day.
  void payloadPreview;

  const outcome = await chat(options.ai, [
    { role: 'system', content: system },
    { role: 'user', content: user },
  ]);

  if (!outcome.ok) {
    return {
      ok: true,
      text: offline.text,
      model: 'offline',
      error: outcome.error,
      fellBack: true,
    };
  }

  const header =
    options.locale === 'zh'
      ? `> 由 ${outcome.model} 生成，基于脱敏统计（脱敏等级：${options.redaction}）。\n\n`
      : `> Generated by ${outcome.model} from redacted statistics (redaction: ${options.redaction}).\n\n`;

  return {
    ok: true,
    text: `${header}${outcome.text}\n\n---\n\n${offline.text}`,
    model: outcome.model,
    fellBack: false,
  };
}

/** Cheap reachability probe used by `attentio doctor` and the settings screen. */
export async function probeAi(config: AiClientConfig): Promise<{ ok: boolean; detail: string }> {
  const outcome = await chat({ ...config, timeoutMs: 15_000 }, [
    { role: 'system', content: 'Reply with the single word: ok' },
    { role: 'user', content: 'ping' },
  ]);
  if (outcome.ok) return { ok: true, detail: `${config.model} at ${chatEndpoint(config.baseUrl)} responded.` };
  return { ok: false, detail: outcome.error ?? 'unknown error' };
}
